from taf.ul.kpi_selector.operations.factory_prototype.classical_factory_prototype import OperationFactoryPrototype
from taf.ul.kpi_selector.operations.rf_unlock.classical_rf_unlock.rf_unlock_prototype import RfUnlock


class RfUnlockFactory(OperationFactoryPrototype):
    def __init__(self):
        super(RfUnlockFactory, self).__init__()

    def get_kpi(self):
        """
        Gets kpi for RF unlock operation.
        :return: dictionary with timeout, requirement and operation description for RF unlock
        :rtype: dict
        """
        return RfUnlock(self.bts).get_kpi()
